scripts.紫轩对话.txt:
	If ($Event == 144) @Label1;
	If ($Event == 170) @Label2;
	Goto @end;

@Label1:	
	//Talk(2079, 2082);
	If ($Talkzx0241 == 0) @Talk0;
	If ($Talkzx0241 == 1) @Talk1;
	Goto @end;
@Talk0:
	If ($ZiXuanSense >> 20) @AddSenseEnd;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd:
	Say("紫轩：杨公子，你是哪里人？", 16);
	Say("杨影枫：我娘生下我就去世了，我爹是江湖中人，四海为家，我从小就跟着我爹到处漂泊，爹死后，我就一个人在深山里长大，所以我也不知道自己的家乡是哪里。", 2);
	Say("紫轩：啊，杨公子，你真可怜。", 16);
	Assign($Talkzx0241, 1);
	Return;
@Talk1:	
	If ($ZiXuanSense >> 20) @AddSenseEnd1;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd1:
	Say("杨影枫：紫轩姑娘，清平乡往哪个方向走？", 2);
	Say("紫轩：<color=Red>西边<color=Black>的路口是去清平乡的。", 16);
	Return;

@Label2:	
	If ($Talkzx0242 == 0) @Talk2;
	If ($Talkzx0242 == 1) @Talk3;
	If ($Talkzx0242 == 2) @Talk4;
	Goto @end;
@Talk2:
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd2:
	Say("紫轩：杨大哥，我常想，一定是老天爷可怜我，才让我遇到了你。", 17);
	Say("杨影枫：紫轩，相信我，只要有我在，我决不会让你再受人欺辱！", 2);
	Assign($Talkzx0242, 1);
	Return;
@Talk3:
	If ($ZiXuanSense >> 20) @AddSenseEnd3;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd3:
	Say("杨影枫：紫轩，你看，这些枫叶多美！", 3);
	Say("紫轩：杨大哥，日后，当你再看到这些枫叶的时候，倘若还能想起我，紫轩也就心满意足了！", 16);
	Say("杨影枫：不，我不会想起你。", 3);
	Say("紫轩：啊？！为……为什么？", 17);
	Say("杨影枫：因为那时你一定就在我的身边，我哪里需要想起你呢？紫轩，以后每年的这个时候，我们都到这里一起观赏枫叶，你说好吗？", 3);
	Say("紫轩：如果真能那样，我就是天下最幸福的女孩了！", 122);
	Assign($Talkzx0242, 2);
	Return;	
@Talk4:
	If ($ZiXuanSense >> 20) @AddSenseEnd4;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd4:
	Say("杨影枫：紫轩，以后每年的这个时候，我们都到这里一起观赏枫叶，你说好吗？", 3);
	Say("紫轩：如果真能那样，我就是天下最幸福的女孩了！", 122);
	Return;	


@end:
	Return;

